check_code:
cyc=['TL','BL','BR','TR','C']
start={'circle':'TL','triangle':'BL','square':'BR','down':'TR','up':'C'}
# figures 1-4 verified by stepping each symbol along the cycle
figs=[{k:cyc[(cyc.index(v)+i)%5] for k,v in start.items()} for i in range(5)]
# observed fig4 (index 3)
assert figs[3]=={'circle':'TR','triangle':'C','square':'TL','down':'BL','up':'BR'}
ans={v:k for k,v in figs[4].items()}
opts={'A':{'TL':'circle','TR':'up','C':'square','BL':'triangle','BR':'down'},
'B':{'TL':'triangle','TR':'up','C':'circle','BL':'square','BR':'down'},
'C':{'TL':'square','TR':'down','C':'circle','BL':'triangle','BR':'up'},
'D':{'TL':'square','TR':'up','C':'triangle','BL':'circle','BR':'down'}}
assert ans==opts['B']
for k in 'ACD': assert ans!=opts[k]

seq='ABCDE'
def step(l): return seq[(seq.index(l)-1)%5]
figs=[dict(TL='A',TR='B',C='E',BL='D',BR='C')]
for i in range(3): figs.append({k:step(v) for k,v in figs[-1].items()})
assert figs[1]==dict(TL='E',TR='A',C='D',BL='C',BR='B')
assert figs[3]==dict(TL='C',TR='D',C='B',BL='A',BR='E')
ans={k:step(v) for k,v in figs[3].items()}
opts={'A':dict(TL='D',TR='B',C='A',BL='C',BR='E'),'B':dict(TL='B',TR='C',C='A',BL='E',BR='D')}
assert ans==opts['B'] and ans!=opts['A']
